import { clickButton } from './support/adventure-controls';
import { test, expect, button, dialog, contract, installCookie } from './support/t056-journey';

// Expectations are literal interpretations of T036 SAVE01–11, not generated by the implementation.
test.describe('T056 independent composed single-slot prepared-state acceptance', () => {
  test('SAVE01 canceled Google and GitHub choices preserve the actual guest room, kit, clues and notes', async ({ journey: j }, _info) => {
    contract('SAVE01'); await j.context.clearCookies(); await j.page.reload();
    await clickButton(j.page, 'New Adventure'); await j.notes('Guest clue: power is not a data link. Café 🧭');
    await clickButton(j.page, 'Talk'); await clickButton(j.page, 'Talk to Photon the Firefly'); await clickButton(j.page, 'Skip dialogue');
    for (const provider of ['Google', 'GitHub'] as const) {
      await clickButton(j.page, 'Save'); const popup = await j.openProvider(provider);
      await clickButton(j.page, 'Cancel sign-in'); await expect.poll(() => popup.isClosed()).toBe(true);
      await j.expectNotes('Guest clue: power is not a data link. Café 🧭');
      await expect(j.page.getByRole('heading', { name: 'The Arrival Lift', exact: true })).toBeVisible();
      await clickButton(j.page, 'Inventory'); await expect(dialog(j.page, 'Inventory')).toContainText('Reusable inspection kit'); await clickButton(j.page, 'Close Inventory');
      await clickButton(j.page, 'Notebook'); await expect(dialog(j.page, 'Notebook')).toContainText('power'); await clickButton(j.page, 'Close notebook');
    }
    expect(j.writes().length).toBe(0); expect(await j.local.inspect()).toBeNull();
    await expect(j.page.getByText(/^Saved at \d{4}-\d{2}-\d{2}T/)).toHaveCount(0);
    expect(await j.page.evaluate(() => ({ local: localStorage.length, session: sessionStorage.length }))).toEqual({ local: 0, session: 0 });
  });

  test('SAVE02 separate synthetic provider accounts restore complete snapshots after actual browser close; no provider verification inferred', async ({ journey: j }, _info) => {
    contract('SAVE02'); await j.start(); await j.notes('GitHub account private clue');
    await clickButton(j.page, 'Talk'); await clickButton(j.page, 'Talk to Photon the Firefly'); await clickButton(j.page, 'Skip dialogue');
    await clickButton(j.page, 'Walk'); await clickButton(j.page, "Walk to The Titan's Workshop"); await expect(j.page.getByRole('heading', { name: "The Titan's Workshop", exact: true })).toBeVisible(); await j.firstSave(); const github = await j.local.inspectSlot();
    expect(github?.snapshot.world.inventory).toEqual([{ itemId: 'spec001:ITEM-inspection-kit', quantity: 1 }]);
    expect(github?.snapshot.notebook.factIds).toContain('spec001:FACT-photon-clue');
    const other = await j.local.syntheticSession('google'); await installCookie(j.context, other.cookie);
    await j.page.reload(); await expect(j.page.getByText('Synthetic T056 Google player (google)', { exact: true })).toBeVisible();
    await j.start(); await j.notes('Google account separate clue'); await j.firstSave(); const google = await j.local.inspectSlot('google');
    expect(google?.snapshot.world.inventory).toEqual([]); expect(google?.snapshot.notebook.factIds).not.toContain('spec001:FACT-photon-clue');
    expect(google?.snapshot.adventureId).not.toBe(github?.snapshot.adventureId);
    for (const [provider, original, room] of [['github', github, "The Titan's Workshop"], ['google', google, 'The Arrival Lift']] as const) {
      await j.restartBrowser(provider); const tab = j.page; await clickButton(tab, 'Continue');
      await expect(tab.getByRole('heading', { name: room, exact: true })).toBeVisible(); await j.expectNotes(original!.snapshot.notebook.personalNotes, tab);
      await clickButton(tab, 'Inventory');
      if (provider === 'github') await expect(dialog(tab, 'Inventory')).toContainText('Reusable inspection kit');
      else await expect(dialog(tab, 'Inventory')).toContainText('Your inventory is empty');
      await clickButton(tab, 'Close Inventory');
      expect(await j.local.inspectSlot(provider)).toEqual(original);
    }
    expect((await j.local.inspectAccount()).saves).toBe(2); expect(j.writes().length).toBe(2);
    await j.page.screenshot({ path: _info.outputPath('T056-browser-return.png'), fullPage: true });
  });

  test('SAVE03 existing slot cancellation and load replace all unsaved inventory and notebook; new adventure needs manual replacement', async ({ journey: j }, _info) => {
    contract('SAVE03'); await j.start(); await j.notes('Durable empty-kit adventure'); await j.firstSave(); const original = await j.local.inspectSlot();
    await j.start(); await j.notes('Different adventure unsaved'); await clickButton(j.page, 'Talk'); await clickButton(j.page, 'Talk to Photon the Firefly'); await clickButton(j.page, 'Skip dialogue');
    await clickButton(j.page, 'Save'); await expect(dialog(j.page, 'Review the account save')).toContainText('Revision: 1.');
    await clickButton(j.page, 'Cancel'); expect(await j.local.inspectSlot()).toEqual(original); await j.expectNotes('Different adventure unsaved');
    await clickButton(j.page, 'Save'); await clickButton(j.page, 'Load Existing Save'); await expect(dialog(j.page, 'Load the server adventure?')).toContainText('unsaved notes');
    await clickButton(j.page, 'Discard current progress and load'); await j.expectNotes('Durable empty-kit adventure');
    await clickButton(j.page, 'Inventory'); await expect(dialog(j.page, 'Inventory')).not.toContainText('Reusable inspection kit'); await clickButton(j.page, 'Close Inventory');
    await j.start(); await j.notes('Explicit replacement'); await clickButton(j.page, 'Save'); await clickButton(j.page, 'Replace With This Adventure');
    expect(await j.local.inspectSlot()).toEqual(original); await clickButton(j.page, 'Confirm replacement');
    await expect.poll(async () => (await j.local.inspectSlot())?.revision).toBe(2); expect((await j.local.inspectSlot())?.snapshot.notebook.personalNotes).toBe('Explicit replacement');
    expect(j.writes().length).toBe(2);
  });

  test('SAVE04–06 autosave off, explicit opt-in, actual unsafe activity, one safe boundary, and new-adventure no-adoption', async ({ journey: j }, _info) => {
    contract('SAVE04', 'SAVE05', 'SAVE06'); await j.start(); await j.notes('Manual anchor'); await j.firstSave();
    await clickButton(j.page, "Walk to The Titan's Workshop"); await clickButton(j.page, 'Walk to The Arrival Lift');
    expect(j.writes().length).toBe(1); expect((await j.local.inspectAccount()).preference?.autosave_enabled).toBe(0);
    await clickButton(j.page, 'Settings'); await expect(dialog(j.page, 'Settings')).toContainText('same account save slot'); await clickButton(j.page, 'Enable account autosave');
    await expect(dialog(j.page, 'Settings')).toContainText('Last confirmed account setting: on.'); await clickButton(j.page, 'Close settings');
    await j.notes('Notes await next safe boundary'); await clickButton(j.page, 'Look'); await clickButton(j.page, 'Look at message capsule'); await clickButton(j.page, 'Save');
    await expect(j.page.getByText(/Finish the current activity before saving/)).toBeVisible(); expect(j.writes().length).toBe(1);
    await clickButton(j.page, 'Return to investigation'); await clickButton(j.page, 'Walk'); await clickButton(j.page, "Walk to The Titan's Workshop");
    await expect.poll(async () => (await j.local.inspectSlot())?.revision).toBe(2); expect((await j.local.inspectSlot())?.snapshot.notebook.personalNotes).toBe('Notes await next safe boundary');
    expect((await j.local.inspectAccount()).saves).toBe(1); expect(j.writes()[1]!.headers['x-save-mode']).toBe('automatic');
    await j.start(); await clickButton(j.page, "Walk to The Titan's Workshop"); expect(j.writes().length).toBe(2);
    await clickButton(j.page, 'Save'); await expect(dialog(j.page, 'Review the account save')).toBeVisible();
  });

  test('SAVE07 independent tabs conflict; keep-playing preserves loser and load replaces it explicitly', async ({ journey: j }, _info) => {
    contract('SAVE07'); await j.start(); await j.notes('Revision one'); await j.firstSave();
    const tab = await j.context.newPage(); await tab.goto(j.local.url); await clickButton(tab, 'Continue'); await j.notes('Losing local changes', tab);
    let release!: () => void; const held = new Promise<void>(resolve => { release = resolve; });
    let reached!: () => void; const pending = new Promise<void>(resolve => { reached = resolve; });
    await tab.route('**/api/v1/save', async route => { if (route.request().method() !== 'PUT') return route.continue(); reached(); await held; await route.continue(); });
    try {
      await clickButton(tab, 'Save'); await pending;
      await j.notes('Winning revision two'); await clickButton(j.page, 'Save'); await expect(j.page.getByText(/^Saved at \d{4}-\d{2}-\d{2}T/)).toBeVisible();
      const winner = await j.local.inspectSlot(); release(); await expect(dialog(tab, 'The server save changed')).toBeVisible();
      await tab.screenshot({ path: _info.outputPath('T056-actual-put-conflict.png'), fullPage: true });
      expect(await j.local.inspectSlot()).toEqual(winner); await clickButton(tab, 'Keep Playing Without Saving'); await j.expectNotes('Losing local changes', tab);
      await clickButton(tab, 'Restore Save'); await clickButton(tab, 'Discard current progress and load'); await j.expectNotes('Winning revision two', tab);
      expect(j.writes().length).toBe(3); expect(j.writes()[1]!.headers['if-match']).toBe('"save-1"');
    } finally { release(); }

  });

  test('SAVE08 lost committed acknowledgement older than current slot requires reconciliation without a second commit', async ({ journey: j }, _info) => {
    contract('SAVE08'); await j.start(); await j.notes('Lost receipt snapshot');
    await j.page.route('**/api/v1/save', async route => { if (route.request().method() !== 'PUT') return route.continue(); expect(await j.local.commitAndLoseResponse(route.request())).toBe(201); await route.abort('failed'); });
    await clickButton(j.page, 'Save'); await clickButton(j.page, 'Save this adventure'); await expect(dialog(j.page, 'Save outcome unconfirmed')).toBeVisible();
    await clickButton(j.page, 'Keep Playing Without Saving'); await j.notes('Later local notes');
    const tab = await j.context.newPage(); await tab.goto(j.local.url); await clickButton(tab, 'Continue'); await j.notes('Other tab current revision', tab); await clickButton(tab, 'Save');
    await expect(tab.getByText(/^Saved at \d{4}-\d{2}-\d{2}T/)).toBeVisible(); const newer = await j.local.inspectSlot();
    await j.page.unroute('**/api/v1/save'); await clickButton(j.page, 'Save'); await clickButton(j.page, 'Retry pending save');
    await expect(dialog(j.page, 'The server save changed')).toBeVisible(); expect(await j.local.inspectSlot()).toEqual(newer);
    const [first, , retry] = j.writes(); expect(retry?.body).toBe(first?.body); expect(retry?.headers['idempotency-key']).toBe(first?.headers['idempotency-key']);
    await clickButton(j.page, 'Keep Playing Without Saving'); await j.expectNotes('Later local notes');
  });

  test('SAVE09 offline attempt keeps confirmed bytes and newer notes; reconnect retries the exact operation', async ({ journey: j }, _info) => {
    contract('SAVE09'); await j.start(); await j.notes('Confirmed anchor'); await j.firstSave(); const anchor = await j.local.inspectSlot();
    await j.notes('Offline attempted snapshot'); await j.context.setOffline(true); await clickButton(j.page, 'Save');
    // Read failure before PUT also cannot claim saved; keep the adventure until reconnect.
    await expect(j.page.getByText(/could not be confirmed/).first()).toBeVisible(); expect(await j.local.inspectSlot()).toEqual(anchor);
    await j.context.setOffline(false); await j.expectNotes('Offline attempted snapshot');
    await j.page.route('**/api/v1/save', route => route.request().method() === 'PUT' ? route.abort('failed') : route.continue());
    await clickButton(j.page, 'Save'); await expect(dialog(j.page, 'Save outcome unconfirmed')).toBeVisible();
    await clickButton(j.page, 'Keep Playing Without Saving'); await j.notes('Newer unsaved notes'); await clickButton(j.page, 'Save'); await j.page.unroute('**/api/v1/save');
    await clickButton(j.page, 'Retry pending save'); await expect(dialog(j.page, 'Save outcome unconfirmed')).toBeHidden();
    expect((await j.local.inspectSlot())?.snapshot.notebook.personalNotes).toBe('Offline attempted snapshot'); await j.expectNotes('Newer unsaved notes');
    await expect(j.page.getByText('Unsaved changes', { exact: true })).toBeVisible();
    await j.page.screenshot({ path: _info.outputPath('T056-offline-newer-notes-dirty.png'), fullPage: true });
    const writes = j.writes(); expect(writes.at(-1)?.body).toBe(writes.at(-2)?.body); expect(writes.at(-1)?.headers['idempotency-key']).toBe(writes.at(-2)?.headers['idempotency-key']);
  });

  test('SAVE09 expiry at native PUT admission preserves slot and in-memory progress for explicit sign-in', async ({ journey: j }, _info) => {
    contract('SAVE09'); await j.start(); await j.notes('Durable before expiry'); await j.firstSave(); const stored = await j.local.inspectSlot(); await j.notes('Unsaved after expiry');
    await j.page.route('**/api/v1/save', async route => { if (route.request().method() === 'PUT') { const headers = await route.request().allHeaders(); await j.local.expireSession(headers['cookie']!); } await route.continue(); });
    await clickButton(j.page, 'Save'); await expect(j.page.getByText(/Sign-in expired/).first()).toBeVisible(); expect(await j.local.inspectSlot()).toEqual(stored);
    await clickButton(j.page, 'Keep Playing Without Saving'); await j.expectNotes('Unsaved after expiry'); await clickButton(j.page, 'Save'); await clickButton(j.page, 'Sign in again');
    await expect(button(j.page, 'GitHub')).toBeVisible(); await expect(button(j.page, 'Google')).toBeVisible(); expect(j.writes().length).toBe(2);
  });

  for (const kind of ['owner-field', 'unsupported-content', 'oversize-body'] as const) test(`SAVE10 native ${kind} rejection preserves both account slots`, async ({ journey: j }, _info) => {
    contract('SAVE10'); await j.start(); await j.notes('GitHub protected'); await j.firstSave();
    await installCookie(j.context, (await j.local.syntheticSession('google')).cookie); await j.page.reload();
    await j.start(); await j.notes('Google protected'); await j.firstSave();
    const github = await j.local.inspectSlot('github'), google = await j.local.inspectSlot('google');
    await installCookie(j.context, (await j.local.syntheticSession('github')).cookie); await j.page.reload(); await clickButton(j.page, 'Continue'); await j.notes('Rejected candidate');
    await j.page.route('**/api/v1/save', async route => {
      if (route.request().method() !== 'PUT') return route.continue();
      const original = route.request().postData()!, payload = JSON.parse(original) as Record<string, unknown>;
      if (kind === 'owner-field') payload['accountId'] = '60000000-0000-4000-8000-000000000002';
      if (kind === 'unsupported-content') payload['contentVersion'] = '99.0.0';
      const body = kind === 'oversize-body' ? original + ' '.repeat(262145 - Buffer.byteLength(original)) : JSON.stringify(payload);
      await route.continue({ postData: body });
    });
    const response = j.page.waitForResponse(value => value.request().method() === 'PUT' && value.url().endsWith('/save'));
    await clickButton(j.page, 'Save'); expect((await response).status()).toBe(kind === 'oversize-body' ? 413 : 422);
    expect(await j.local.inspectSlot('github')).toEqual(github); expect(await j.local.inspectSlot('google')).toEqual(google);
    await expect(j.page.getByText(/^Saved at \d{4}-\d{2}-\d{2}T/)).toHaveCount(0); expect(j.writes().length).toBe(3);
  });

  for (const version of ['0.9.0', '99.0.0']) test(`SAVE10–11 unsupported stored content ${version} retains exact bytes and blocks load/replacement`, async ({ journey: j }, _info) => {
    contract('SAVE10', 'SAVE11'); await j.start(); await j.notes('Preserve original historical content'); await j.firstSave(); await j.local.storedContent(version); const original = await j.local.inspectSlot();
    await j.page.reload(); await clickButton(j.page, 'Continue'); await expect(dialog(j.page, 'Save preserved')).toBeVisible();
    await expect(button(j.page, 'Load Existing Save')).toBeHidden(); await expect(button(j.page, 'Replace With This Adventure')).toBeHidden();
    expect(await j.local.inspectSlot()).toEqual(original); expect(j.writes().length).toBe(1);
    // This is intentionally NOT T036's hypothetical supported migration / future door integration.
  });
});
